/**
 * The texts `LATEX_SYMBOL_CONSTANTS` carries twice, sorted.
 *
 * Each appears once as `symbols` and once as `operant`,
 * in that order, and the two are different grammars: `operant` matches
 * the bare text *or* the backslashed text, `symbols` only the
 * backslashed one. Every entry was verified by parsing both spellings
 * through the gem before emission — bare reads as `{operant}` and
 * backslashed as `{symbols}`, the sole exception being `\;`, which
 * `symbol_class_commands` claims as `:three_per_em_space` two
 * alternatives earlier.
 */
export const LATEX_SYMBOL_CONSTANT_COLLISIONS: readonly string[] = [
  "!",
  "#",
  "$",
  "%",
  "&",
  "'",
  "+",
  ",",
  "-",
  ".",
  "/",
  ":",
  ";",
  "<",
  "=",
  ">",
  "?",
  "@",
  "^",
];

/**
 * Decimal marker -> the text `decimal_marker` (`latex/parse.rb:205`)
 * actually matches.
 *
 * The gem does not match the marker: it matches
 * `Utility.string_to_html_entity(marker)`, because `Latex::Parser`
 * entity-encodes its input before Parslet sees it. `.` and `,` encode to
 * themselves; `ar`/`fa`'s U+066B encodes to seven characters. Keyed by
 * every marker `src/formatting` can resolve, each verified under its own
 * locale by a live parse and refuted under the others.
 */
export const LATEX_ENCODED_DECIMAL_MARKERS: ReadonlyMap<string, string> = new Map([
  [",", ","],
  [".", "."],
  ["٫", "&#x66b;"],
]);
